import { Peptide } from "./types";

function slug(name: string) {
    return name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
}

function p(raw: Omit<Peptide, "slug">): Peptide {
    return { ...raw, slug: slug(raw.name) };
}

